for(const table of window.TOPIC_DISTRIBUTIONS.tables)for(const row of table.rows)row.bookSections=row.bookSections.flatMap(ref=>{const g=window.BOOK_GUIDES[ref.lessonId],pages=ref.pages.filter(p=>g.sections.some(s=>s.pages.includes(p)));if(!pages.length)return [];const preferred=g.sections[ref.sectionIndex];if(preferred&&pages.every(p=>preferred.pages.includes(p)))return [{...ref,pages,title:preferred.title}];return g.sections.flatMap((s,sectionIndex)=>{const overlap=pages.filter(p=>s.pages.includes(p));return overlap.length?[{...ref,pages:overlap,sectionIndex,title:s.title}]:[];});});
